@dataclass
class Evaluation:
    "An evaluation and its documents, displayed as a summary card in notebooks"
    id:str    # MD5 hash of the evaluation's `Title`, `Year` and `Project Code`
    docs:list # Documents, each a dict with `subtype`, `url` and `desc`
    meta:dict # The other CSV columns, such as `Title`, `Year` and `Countries Covered`

    def _repr_markdown_(self):
        title = self.meta.get('Title', 'Untitled')
        year = self.meta.get('Year', 'n/a')
        org = self.meta.get('Evaluation Commissioner', 'Unknown')
        countries = self.meta.get('Countries Covered', [])
        country_str = ', '.join(countries[:3]) if countries else 'Not specified'
        if len(countries) &gt; 3: country_str += f' (+{len(countries)-3} more)'

        return f"""
### {title}
**Year:** {year} | **Organization:** {org} | **Countries:** {country_str}

**Documents:** {len(self.docs)} available  
**ID:** `{self.id}`
"""
